WITH cleaned AS (SELECT *, CASE WHEN event_type IN ('search', 'click') THEN 'Priority' ELSE 'Other' END AS event_type_group FROM web_events WHERE page IS NOT NULL) SELECT id, event_type, event_time, event_type_group, PERCENT_RANK() OVER (ORDER BY duration_sec NULLS FIRST) AS duration_sec_percent_rank, AVG(duration_sec) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_5_prior, ROW_NUMBER() OVER (PARTITION BY page ORDER BY event_time DESC, id) AS row_seq FROM cleaned;
